"use client";

import { useId, useState } from "react";
import type { ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { Transition } from "motion/react";
import { ChevronDown, ShieldQuestion, Undo2 } from "lucide-react";
import { motionTokens } from "@/lib/motion-tokens";
import styles from "./approval-card.module.css";

export type ApprovalStatus = "pending" | "approved" | "rejected";

export interface ApprovalDetail {
  /** Name of the fact, such as "Amount". */
  label: string;
  /** Its value. */
  value: ReactNode;
}

/**
 * A request for a person's decision before an agent acts. It states the action, keeps the fine print behind a details toggle, and
 * once approved or rejected it settles into a resolved state: the icon turns into a drawn check or cross and the buttons give
 * way to the outcome, with an undo.
 */
export interface ApprovalCardProps {
  /** The action waiting for a decision, in one line. */
  title: string;
  /** A sentence or two on what will happen and why. */
  summary?: ReactNode;
  /** Who is asking, shown above the title (an agent or a workflow name). */
  source?: string;
  /** Icon of the request while it is pending. */
  icon?: ReactNode;
  /** Facts shown when the details are open, as label and value rows. */
  details?: ApprovalDetail[];
  /** Extra content under the detail rows, such as a preview of the change. */
  children?: ReactNode;
  /** Controlled decision. */
  status?: ApprovalStatus;
  /** Decision the card starts with when uncontrolled. */
  defaultStatus?: ApprovalStatus;
  /** Called when the person approves, rejects or undoes. */
  onStatusChange?: (status: ApprovalStatus) => void;
  /** Controlled open state of the details. */
  detailsOpen?: boolean;
  /** Whether the details start open when uncontrolled. */
  defaultDetailsOpen?: boolean;
  /** Called when the details toggle is pressed. */
  onDetailsOpenChange?: (open: boolean) => void;
  /** Text of the approve button. */
  approveLabel?: string;
  /** Text of the reject button. */
  rejectLabel?: string;
  /** Outcome text per decision, shown in the resolved state. */
  resolvedLabels?: Partial<Record<Exclude<ApprovalStatus, "pending">, string>>;
  /** Offers an undo in the resolved state that returns the card to pending. */
  allowUndo?: boolean;
  /** Extra class for the root element. */
  className?: string;
}

const standard = [...motionTokens.ease.standard] as [number, number, number, number];
const enterEase = [...motionTokens.ease.enter] as [number, number, number, number];
const fade: Transition = { duration: motionTokens.duration.fast, ease: standard };
const draw: Transition = { duration: 0.3, ease: standard, delay: 0.1 };
const defaultResolved = { approved: "Approved", rejected: "Rejected" };

export function ApprovalCard({ title, summary, source, icon, details, children, status, defaultStatus = "pending", onStatusChange, detailsOpen, defaultDetailsOpen = false, onDetailsOpenChange, approveLabel = "Approve", rejectLabel = "Reject", resolvedLabels, allowUndo = true, className }: ApprovalCardProps) {
  const reduce = !!useReducedMotion();
  const detailsId = useId();
  const titleId = useId();
  const [ownStatus, setOwnStatus] = useState<ApprovalStatus>(defaultStatus);
  const [ownOpen, setOwnOpen] = useState(defaultDetailsOpen);
  const state = status ?? ownStatus;
  const open = detailsOpen ?? ownOpen;
  const hasDetails = (details?.length ?? 0) > 0 || children != null;
  const resolved = { ...defaultResolved, ...resolvedLabels };

  function decide(next: ApprovalStatus) {
    if (status === undefined) setOwnStatus(next);
    onStatusChange?.(next);
  }
  function toggle() {
    if (detailsOpen === undefined) setOwnOpen(!open);
    onDetailsOpenChange?.(!open);
  }

  const glyph = reduce
    ? { initial: { opacity: 0 }, animate: { opacity: 1 }, exit: { opacity: 0 }, transition: fade }
    : { initial: { opacity: 0, scale: 0.5, filter: `blur(${motionTokens.blur.subtle}px)` }, animate: { opacity: 1, scale: 1, filter: "blur(0px)" }, exit: { opacity: 0, scale: 0.5, filter: `blur(${motionTokens.blur.subtle}px)`, transition: fade }, transition: { ...motionTokens.spring.snappy, opacity: fade, filter: fade } };
  const footer = reduce
    ? { initial: { opacity: 0 }, animate: { opacity: 1 }, exit: { opacity: 0 }, transition: fade }
    : { initial: { opacity: 0, y: 10, filter: `blur(${motionTokens.blur.soft}px)` }, animate: { opacity: 1, y: 0, filter: "blur(0px)" }, exit: { opacity: 0, y: -8, filter: `blur(${motionTokens.blur.subtle}px)`, transition: fade }, transition: { duration: motionTokens.duration.standard, ease: enterEase } };
  const stroke = reduce ? { initial: false as const } : { initial: { pathLength: 0 }, animate: { pathLength: 1 }, transition: draw };

  return (
    <section className={[styles.root, className].filter(Boolean).join(" ")} data-status={state} aria-labelledby={titleId}>
      <header className={styles.header}>
        <span className={styles.badge} aria-hidden="true">
          {/* One ripple leaves the badge at the moment of the decision. */}
          {state !== "pending" && !reduce ? <motion.span key={state} className={styles.ripple} initial={{ opacity: 0.55, scale: 1 }} animate={{ opacity: 0, scale: 1.9 }} transition={{ duration: 0.6, ease: standard }} /> : null}
          <AnimatePresence mode="popLayout" initial={false}>
            {state === "pending"
              ? <motion.span key="pending" className={styles.glyph} {...glyph}>{icon ?? <ShieldQuestion width={19} height={19} strokeWidth={1.8} />}</motion.span>
              : <motion.span key={state} className={styles.glyph} {...glyph}>
                  <svg className={styles.sign} viewBox="0 0 20 20">
                    {state === "approved"
                      ? <motion.path d="M4.6 10.4 8.4 14 15.4 6.2" {...stroke} />
                      : <><motion.path d="M5.8 5.8 14.2 14.2" {...stroke} /><motion.path d="M14.2 5.8 5.8 14.2" {...stroke} transition={reduce ? undefined : { ...draw, delay: 0.2 }} /></>}
                  </svg>
                </motion.span>}
          </AnimatePresence>
        </span>
        <div className={styles.heading}>
          {source ? <p className={styles.source}>{source}<span className={styles.sourceNote}>{state === "pending" ? " needs your approval" : ""}</span></p> : null}
          <h3 id={titleId} className={styles.title}>{title}</h3>
        </div>
      </header>

      {summary ? <p className={styles.summary}>{summary}</p> : null}

      {hasDetails ? (
        <div className={styles.details}>
          <button type="button" className={styles.toggle} aria-expanded={open} aria-controls={detailsId} onClick={toggle}>
            <ChevronDown className={styles.chevron} width={15} height={15} strokeWidth={2} aria-hidden="true" />
            {open ? "Hide details" : "Show details"}
          </button>
          <AnimatePresence initial={false}>
            {open ? (
              <motion.div key="details" id={detailsId} className={styles.region} initial={reduce ? { opacity: 0 } : { height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={reduce ? { opacity: 0 } : { height: 0, opacity: 0 }} transition={reduce ? fade : { height: motionTokens.spring.smooth, opacity: { duration: motionTokens.duration.standard, ease: standard } }}>
                <div className={styles.panel}>
                  {details?.length ? (
                    <dl className={styles.facts}>
                      {details.map((detail, index) => (
                        <motion.div key={detail.label} className={styles.fact} initial={reduce ? false : { opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: motionTokens.duration.standard, ease: enterEase, delay: 0.04 + Math.min(index * motionTokens.stagger.item, 0.3) }}>
                          <dt>{detail.label}</dt>
                          <dd>{detail.value}</dd>
                        </motion.div>
                      ))}
                    </dl>
                  ) : null}
                  {children != null ? <div className={styles.extra}>{children}</div> : null}
                </div>
              </motion.div>
            ) : null}
          </AnimatePresence>
        </div>
      ) : null}

      <footer className={styles.footer}>
        <AnimatePresence mode="popLayout" initial={false}>
          {state === "pending" ? (
            <motion.div key="actions" className={styles.actions} {...footer}>
              <button type="button" className={styles.reject} onClick={() => decide("rejected")}>{rejectLabel}</button>
              <button type="button" className={styles.approve} onClick={() => decide("approved")}>{approveLabel}</button>
            </motion.div>
          ) : (
            <motion.div key={state} className={styles.outcome} role="status" {...footer}>
              <span className={styles.outcomeText}><span className={styles.dot} aria-hidden="true" />{resolved[state]}</span>
              {allowUndo ? <button type="button" className={styles.undo} onClick={() => decide("pending")}><Undo2 width={14} height={14} strokeWidth={2} aria-hidden="true" />Undo</button> : null}
            </motion.div>
          )}
        </AnimatePresence>
      </footer>
    </section>
  );
}

export default ApprovalCard;

/* --approval-tone follows the decision: neutral while pending, success once approved, danger once rejected. */
.root { --approval-tone: var(--border-strong); position: relative; display: flex; width: 100%; min-width: 0; box-sizing: border-box; flex-direction: column; gap: var(--space-3); padding: var(--space-5); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); color: var(--foreground); box-shadow: var(--shadow-raised); font-family: var(--font-body); letter-spacing: var(--tracking-body); text-align: left; transition: border-color var(--duration-considered) var(--ease-standard), box-shadow var(--duration-considered) var(--ease-standard); }
.root[data-status="approved"] { --approval-tone: var(--success); }
.root[data-status="rejected"] { --approval-tone: var(--danger); }
.root:not([data-status="pending"]) { border-color: color-mix(in oklab, var(--approval-tone) 38%, var(--border)); box-shadow: var(--shadow-resting); }

.header { display: flex; min-width: 0; align-items: center; gap: var(--space-3); }
.badge { position: relative; display: grid; width: 40px; height: 40px; flex: none; place-items: center; border-radius: var(--radius-pill); background: var(--accent); color: var(--accent-foreground); transition: background-color var(--duration-standard) var(--ease-standard), color var(--duration-standard) var(--ease-standard); }
.root:not([data-status="pending"]) .badge { background: color-mix(in oklab, var(--approval-tone) 16%, var(--surface)); color: var(--approval-tone); }
.ripple { position: absolute; inset: 0; border: 1.5px solid var(--approval-tone); border-radius: inherit; pointer-events: none; }
.glyph { display: grid; grid-area: 1 / 1; place-items: center; }
.sign { display: block; width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
.heading { display: grid; min-width: 0; gap: 1px; }
.source { margin: 0; color: var(--text-secondary); font-size: var(--text-xs); font-weight: 500; line-height: 1.4; }
.sourceNote { color: var(--text-muted); font-weight: 400; }
.title { margin: 0; font-family: var(--font-display); font-size: var(--text-base); font-weight: 600; letter-spacing: var(--tracking-display); line-height: 1.3; overflow-wrap: anywhere; }
.summary { margin: 0; color: var(--text-secondary); font-size: var(--text-sm); line-height: 1.55; }

.details { display: flex; min-width: 0; flex-direction: column; }
.toggle { display: inline-flex; height: 28px; align-items: center; align-self: flex-start; gap: 5px; margin-left: -8px; padding: 0 10px 0 7px; border: 0; border-radius: var(--radius-pill); background: transparent; color: var(--text-secondary); font: inherit; font-size: var(--text-sm); font-weight: 500; cursor: pointer; -webkit-tap-highlight-color: transparent; transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard); }
.chevron { flex: none; transition: rotate var(--duration-spring) var(--ease-spring); }
.toggle[aria-expanded="false"] .chevron { rotate: -90deg; }
.region { overflow: hidden; }
.panel { display: grid; gap: var(--space-3); margin-top: var(--space-2); padding: var(--space-3) var(--space-4); border-radius: var(--radius-control); background: var(--surface-muted); }
.facts { display: grid; gap: var(--space-2); margin: 0; }
.fact { display: flex; min-width: 0; align-items: baseline; justify-content: space-between; gap: var(--space-4); font-size: var(--text-sm); line-height: 1.45; }
.fact dt { flex: none; color: var(--text-muted); }
.fact dd { min-width: 0; margin: 0; font-weight: 500; text-align: right; overflow-wrap: anywhere; }
.extra { min-width: 0; color: var(--text-secondary); font-size: var(--text-sm); line-height: 1.5; }

.footer { position: relative; display: grid; min-height: 40px; margin-top: var(--space-1); }
.actions, .outcome { display: flex; min-width: 0; grid-area: 1 / 1; align-items: center; gap: var(--space-2); }
.actions { justify-content: flex-end; }
.approve, .reject { height: 40px; flex: 0 1 auto; padding: 0 var(--space-5); border: 1px solid transparent; border-radius: var(--radius-pill); font: inherit; font-size: var(--text-sm); font-weight: 600; white-space: nowrap; cursor: pointer; -webkit-tap-highlight-color: transparent; transition: scale var(--duration-spring) var(--ease-spring), background-color var(--duration-fast) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard); }
.approve { background: var(--accent); color: var(--accent-foreground); }
.reject { border-color: var(--border); background: var(--surface); color: var(--foreground); }
/* Quick press, spring release. */
.approve:active, .reject:active, .undo:active { scale: .96; transition-duration: var(--duration-instant); transition-timing-function: var(--ease-standard); }
.outcome { justify-content: space-between; }
.outcomeText { display: inline-flex; min-width: 0; align-items: center; gap: var(--space-2); color: var(--approval-tone); font-size: var(--text-sm); font-weight: 600; }
.dot { width: 7px; height: 7px; flex: none; border-radius: var(--radius-pill); background: currentColor; }
.undo { display: inline-flex; height: 32px; flex: none; align-items: center; gap: 6px; padding: 0 var(--space-3); border: 0; border-radius: var(--radius-pill); background: transparent; color: var(--text-secondary); font: inherit; font-size: var(--text-sm); font-weight: 500; cursor: pointer; -webkit-tap-highlight-color: transparent; transition: scale var(--duration-spring) var(--ease-spring), background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard); }
@media (hover: hover) and (pointer: fine) {
  .toggle:hover, .undo:hover { background: var(--surface-muted); color: var(--foreground); }
  .approve:hover { background: color-mix(in oklab, var(--accent), var(--accent-foreground) 9%); }
  .reject:hover { border-color: color-mix(in oklab, var(--danger) 45%, var(--border)); color: var(--danger); }
}
@media (max-width: 26rem) { .actions > * { flex: 1; } }

@media (prefers-reduced-motion: reduce) {
  .root, .badge, .toggle, .chevron, .approve, .reject, .undo { transition: none; }
  .approve:active, .reject:active, .undo:active { scale: none; }
}
